const seq = [{ move: 400, speed: 200 }, { move: -400, speed: 200 }];
const i = context.get('step') || 0;
context.set('step', (i + 1) % seq.length);
msg.payload = seq[i];
return msg;

if (msg.payload.fault) {
    node.warn('TMC2130 fault bitmask: ' + msg.payload.fault);
    return msg;
}
if (msg.payload.tstep !== undefined && msg.payload.sg_result < 100) {
    node.warn('TMC2130 SG_RESULT low: ' + msg.payload.sg_result);
    return msg;
}
return null;
